def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    strong_pressure = 0
    cindy_bid = None
    cindy_alive = False

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 90:
                    strong_pressure += 1
            if oid == 'Cindy':
                cindy_alive = True
                if bid is not None:
                    cindy_bid = float(bid)

    if not alive_opps:
        return float(min(budget, 8.0))

    expected_slots = max(1, int(float(supply) / WATER_REQ))
    alive_count = len(alive_opps) + 1
    scarcity = alive_count - expected_slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    base = 18.0

    if scarcity >= 3:
        base = 52.0
    elif scarcity == 2:
        base = 40.0
    elif scarcity == 1:
        base = 28.0

    if cindy_alive and cindy_bid is not None:
        if cindy_bid >= 120:
            base = min(base, 24.0) if hp >= 5 and no_water == 0 else max(base, 72.0)
        elif cindy_bid >= 80:
            base = max(base, 34.0)

    if highest_prev >= 150:
        if hp >= 5 and no_water == 0:
            base = min(base, 20.0)
        else:
            base = max(base, 78.0)
    elif highest_prev >= 90:
        base = max(base, 32.0)

    if hp <= 2 or no_water >= 2:
        base = max(base, 88.0)
    elif hp <= 4 or no_water >= 1:
        base = max(base, 62.0)

    if day >= 8:
        base = max(base, 42.0)
    if day >= 9 and (hp <= 4 or no_water >= 1):
        base = max(base, 85.0)

    reserve_days = max(0, 10 - int(day))
    soft_cap = budget
    if reserve_days > 0:
        soft_cap = min(budget, max(25.0, budget / float(reserve_days)))

    bid = min(base, soft_cap)

    if hp >= 6 and no_water == 0 and strong_pressure >= 2:
        bid = min(bid, 22.0)

    if budget < 25:
        bid = budget

    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    bid_amount = DAILY_SALARY * 0.6

    # Survival logic: Prioritize water if HP is low
    if my_status['hp'] <= 2:
        bid_amount = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 4:
        bid_amount = DAILY_SALARY * 0.8

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents bid high, be aggressive
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] <= 6:
                bid_amount = max(bid_amount, highest_prev_bid + 5.0)
            else:
                bid_amount = max(bid_amount, highest_prev_bid * 0.98)
        # If opponents bid low, try to win cheaply
        elif highest_prev_bid < DAILY_SALARY * 0.5:
            if my_status['hp'] > 4:
                bid_amount = min(bid_amount, highest_prev_bid + 10.0)
            else:
                bid_amount = max(bid_amount, highest_prev_bid + 20.0)
        else: # Moderate previous bids
            bid_amount = max(bid_amount, highest_prev_bid + 2.0)

    # End game adjustment: Increase aggression if nearing the end and HP isn't full
    if day_context['day'] >= EPISODE_DAYS - 3 and my_status['hp'] < EPISODE_DAYS:
        bid_amount = max(bid_amount, DAILY_SALARY * 0.85)

    final_bid = min(my_status['budget'], bid_amount)

    if final_bid <= 0 and my_status['budget'] > 0:
        return 1.0

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] <= 3:
        bid = max(avg_prev_bid * 1.2, 90.0)
    else:
        bid = avg_prev_bid * 1.05

    return float(min(my_status['budget'], bid))
